package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTlDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujood)", "(Ang Allah ay) Pinakamaluwalhati, Kabanal-banalan, Panginoon ng mga anghel at ng Espiritu (Jibril).", "Sa ruku at sujood.", "Ang Propeta ﷺ ay binigkas ito sa ruku at sujood."),
        "dua_sujood_dhanbi_kullah" to DuaText("Sa Sujood: Patawarin ang Lahat ng Aking Mga Kasalanan", "O Allah, patawarin mo ako sa lahat ng aking mga kasalanan - ang maliit at ang malaki, ang una at ang huli, ang bukas at ang nakatago.", "Sa sujood.", "Ang pagpapatirapa ay isang lugar kung saan sinasagot ang mga duas."),
        "dua_sujood_ridaka" to DuaText("Kanlungan sa Iyong Kasiyahan", "O Allah, ako ay nagpapakupkop sa Iyong kasiyahan mula sa Iyong galit, sa Iyong pagpapatawad sa Iyong kaparusahan, at ako ay nagpapakupkop sa Iyo mula sa Iyo. Hindi kita lubusang mapupuri; Ikaw ay gaya ng pagpuri mo sa iyong sarili.", "Sa sujood — narinig ni Aisha (RA) ang Propeta ﷺ na nagsabi nito.", "Isang sujood dua ng Propeta ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Ang lahat ng pandiwang, pisikal at pinansyal na pagsamba ay para kay Allah. Sumainyo nawa ang kapayapaan, O Propeta, at ang awa ng Allah at ang Kanyang mga pagpapala. Sumainyo nawa ang kapayapaan at sa mga matuwid na lingkod ng Allah. Ako ay sumasaksi na walang sinumang karapat-dapat sambahin maliban kay Allah, at ako ay sumasaksi na si Muhammad ﷺ ay Kanyang alipin at Sugo.", "Sa bawat pag-upo — isinalaysay ni Abdullah ibn Mas'ud (RA) (ang gawaing Hanafi).", "Itinuro ito ng Propeta ﷺ tulad ng isang surah ng Quran."),
        "dua_sajdah_tilawah" to DuaText("Sajdah ng Pagbigkas", "Ang aking mukha ay nagpatirapa sa Isa na lumikha nito at naglabas ng kanyang pandinig at paningin sa pamamagitan ng Kanyang kapangyarihan at kapangyarihan.", "Sa pagpapatirapa ng pagbigkas.", "Ang Propeta ﷺ ay nagsabi nito sa pagpapatirapa ng pagbigkas sa gabi."),
        "dua_after_witr" to DuaText("Pagkatapos ng Witr", "Luwalhati sa Hari, ang Kabanal-banalan.", "Tatlong beses pagkatapos ng salam ng witr, pagtataas ng boses sa pangatlong beses.", "Ang Propeta ﷺ ay nagsabi nito pagkatapos ng witr."),
        "dua_tahajjud_nur" to DuaText("Tahajjud Pambungad na Pagsusumamo", "O Allah, sa Iyo ang papuri; Ikaw ang Tagapagtaguyod ng mga langit, lupa at lahat ng nasa loob nito. Sa Iyo ang papuri; Ikaw ang Liwanag ng langit, lupa at lahat ng nasa loob nito. Sa Iyo ang papuri; Ikaw ang Katotohanan, ang Iyong pangako ay totoo, ang pakikipagtagpo sa Iyo ay totoo, ang Iyong salita ay totoo, Paraiso ay totoo, Impiyerno ay totoo, ang mga Propeta ay totoo, Muhammad ﷺ ay totoo at ang Oras ay totoo.", "Kapag sinimulan ang pagdarasal sa gabi (tahajjud) (ang pambungad na bahagi ng dua).", "Binibigkas ito ng Propeta ﷺ sa pagbangon para sa tahajjud (ang buong dua ay nasa al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Gabayan Ako sa Mga Pinagtatalunang Usapin", "O Allah, Panginoon ni Jibril, Mika'il at Israfil, Tagapaglikha ng mga langit at lupa, Tagaalam ng hindi nakikita at nakikita! Ikaw ang hahatol sa pagitan ng Iyong mga lingkod sa kung ano ang dati nilang pinagkaiba. Patnubayan mo ako sa pamamagitan ng Iyong pahintulot sa katotohanan sa kung ano ang pinag-iba-iba. Tunay na pinatnubayan Mo ang sinumang Iyong ibig sa isang tuwid na landas.", "Sa pagsisimula ng tahajjud — para sa patnubay sa katotohanan sa gitna ng hindi pagkakasundo.", "Sinimulan ng Propeta ﷺ ang kanyang pagdarasal sa gabi sa pamamagitan ng dalawang ito."),
        "dua_going_to_mosque_nur" to DuaText("Pagpunta sa Mosque (Dua ng Liwanag)", "O Allah, ilagay mo ang liwanag sa aking puso, liwanag sa aking mga mata, liwanag sa aking mga tainga, liwanag sa aking kanan, liwanag sa aking kaliwa, liwanag sa itaas ko, liwanag sa ibaba ko, liwanag sa harap ko, liwanag sa likod ko, at liwanagan mo ako.", "Habang papunta sa mosque para sa Fajr.", "Ang Propeta ﷺ ay binibigkas ito kapag lumabas para sa pagdarasal."),
        "dua_waswasa_salah" to DuaText("Waswasa Sa Panahon ng Salah (Khinzab)", "Ako ay nagpapakupkop kay Allah mula sa Shaytan, ang isinumpa.", "Kapag dumarating ang mga bulong ni satanas habang nagdarasal, humanap ng kanlungan at tuyuin nang bahagya sa kaliwa ng tatlong beses.", "Si Uthman ibn Abil-'As (RA) ay ginawa ito at ang mga bulong ay umalis."),
        "dua_alimal_ghayb" to DuaText("Maalam sa Hindi Nakikita", "O Allah, Maalam sa hindi nakikita at nakikita, Tagapaglikha ng mga langit at lupa, Panginoon at Soberano ng lahat ng bagay! Ako ay sumasaksi na walang diyos maliban sa Iyo. Ako ay nagpapakupkop sa Iyo mula sa kasamaan ng aking sarili, at mula sa kasamaan ni Shaytan at sa kanyang (tawag sa) shirk.", "Umaga, gabi at bago matulog — itinuro ito ng Propeta ﷺ kay Abu Bakr (RA).", "Proteksyon mula sa kasamaan ng sarili at ng Shaytan."),
        "dua_fitratil_islam" to DuaText("Sa Fitrah ng Islam", "Kami ay pumasok sa umaga sa fitrah ng Islam, sa salita ng katapatan, sa relihiyon ng ating Propeta Muhammad ﷺ at sa landas ng ating amang si Ibrahim (AS), na matuwid at isang Muslim, at hindi kabilang sa mga polytheist.", "Sa umaga.", "Pagbabago ng pananampalataya tuwing umaga."),
        "dua_amsayna_fitrah" to DuaText("Gabi sa Fitrah ng Islam", "Kami ay pumasok sa gabi sa fitrah ng Islam, sa salita ng katapatan, sa relihiyon ng ating Propeta Muhammad ﷺ at sa landas ng ating amang si Ibrahim (AS), na matuwid at isang Muslim, at hindi kabilang sa mga polytheists.", "Sa gabi.", "Pagbabago ng pananampalataya tuwing gabi."),
        "dua_tahleel_10_fajr" to DuaText("Sampung Tahleel Pagkatapos ng Fajr at Maghrib", "Walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal. Sa kanya ang kapangyarihan at sa kanya ang papuri; Siya ang nagbibigay ng buhay at nagiging sanhi ng kamatayan, at Siya ay may kapangyarihan sa lahat ng bagay.", "Sampung beses pagkatapos ng Fajr (at Maghrib), bago lumipat mula sa iyong pag-upo o pagsasalita.", "Sampung mabuting gawa, sampung kasalanan ang nabura, sampung ranggo na itinaas at proteksyon mula kay Shaytan sa buong araw."),
        "dua_la_hawla_kanz" to DuaText("Isang Kayamanan ng Jannah", "Walang kapangyarihan at walang kapangyarihan maliban kay Allah.", "Kadalasan, sa lahat ng oras.", "Ito ay isa sa mga kayamanan ng Paraiso."),
        "dua_four_beloved_words" to DuaText("Ang Apat na Pinakamamahal na Salita", "Luwalhati sa Allah, ang lahat ng papuri ay para sa Allah, walang sinumang karapat-dapat sambahin maliban kay Allah, at si Allah ang Pinakamadakila.", "Ang mga salita na pinakamamahal sa Allah.", "Sila ay mas mahal sa Propeta ﷺ kaysa sa lahat ng bagay na sinisikatan ng araw."),
        "dua_two_light_words" to DuaText("Dalawang Salita Liwanag sa Dila", "Luwalhati kay Allah at ang lahat ng papuri ay sa Kanya; luwalhati kay Allah, ang Dakila.", "Magaan sa dila, mabigat sa Scale.", "Minamahal sa Pinakamaawain, magaan sa dila at mabigat sa Sukat. (Ang huling hadith ni al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "O May-ari ng Kamahalan at Karangalan!", "Panghawakan ito sa dua - ang ﷺ tagubilin ng Propeta.", "Ang Propeta ﷺ ay nagsabi: kumapit sa 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("Sa Pangalan Mo Ako'y Nakahiga", "Sa Iyong pangalan, aking Panginoon, ako'y humihiga at sa Iyong pangalan ay bumangon ako. Kung kukunin Mo ang aking kaluluwa, maawa ka rito, at kung palayain Mo ito, protektahan mo ito gaya ng pagprotekta Mo sa Iyong matuwid na mga lingkod.", "Pagkatapos mag-alis ng alikabok sa kama at humiga.", "Ipinagkatiwala ang kaluluwa sa Allah bago matulog."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Nilikha Mo ang Aking Kaluluwa", "O Allah, nilikha Mo ang aking kaluluwa at kukunin Mo ito. Ang kamatayan nito at ang buhay nito ay sa Iyo. Kung pananatilihin Ninyo itong buhay, protektahan ito, at kung gagawin Ninyo itong mamatay, patawarin ito. O Allah, hinihiling ko sa Iyo ang kapakanan.", "Bago matulog - isinalaysay ni Ibn Umar (RA).", "Ang Propeta ﷺ ay nag-utos na sabihin ito sa oras ng pagtulog."),
        "dua_sleep_atamana" to DuaText("Pasasalamat Bago Matulog", "Ang lahat ng papuri ay para sa Allah na nagpakain sa atin, nagpainom sa atin, nagpasya at nagbigay sa atin ng kanlungan. Ilan ba ang walang makakasapat o masisilungan.", "Kapag matutulog na.", "Sinabi ito ng Propeta ﷺ nang matulog."),
        "dua_sleep_rabbas_samawat" to DuaText("Lord of the Heavens — Bayaran ang Aming Utang", "O Allah, Panginoon ng mga langit, ang lupa at ang Makapangyarihang Trono, ang aming Panginoon at Panginoon ng lahat ng bagay, ang Tagapaghati ng binhi at ang dating-bato, Tagapaghayag ng Torah, ng Injil at ng Furqan! Humihingi ako ng kanlungan sa Iyo mula sa kasamaan ng lahat na hawak Mo ang noo. O Allah, Ikaw ang Una, walang nauna sa Iyo; Ikaw ang Huli, walang susunod sa Iyo; Ikaw ang Manipesto, walang higit sa Iyo; Ikaw ang Nakatago, walang nakatago sa Iyo. Bayad sa aming utang at palayain kami sa kahirapan.", "Bago matulog, nakahiga sa kanang bahagi - itinuro kay Fatimah (RA).", "Isang panalangin para sa kaluwagan mula sa utang at kahirapan."),
        "dua_sleep_fear" to DuaText("Takot o Pagkabalisa sa Pagtulog", "Ako ay nagpapakupkop sa perpektong mga salita ni Allah mula sa Kanyang galit at Kanyang kaparusahan, mula sa kasamaan ng Kanyang mga alipin, at mula sa mga bulong ng mga demonyo at mula sa kanilang paglapit sa akin.", "Kapag nakakaramdam ng takot o pagkabalisa sa pagtulog.", "Sa paggawa nito, hindi siya makakasama ng bagay na iyon."),
        "dua_waking_afani" to DuaText("Paggising: Ibinalik Niya ang Aking Kaluluwa", "Ang lahat ng papuri ay para sa Allah na nagbigay ng kagalingan sa aking katawan, ibinalik ang aking kaluluwa sa akin at pinahintulutan akong alalahanin Siya.", "Sa paggising.", "Pasasalamat sa bagong umaga."),
        "dua_allahu_rabbi" to DuaText("Allah, si Allah ang Aking Panginoon", "Allah, si Allah ang aking Panginoon; Wala akong iniuugnay sa Kanya.", "Sa kalungkutan o pagkabalisa — itinuro ito ng Propeta ﷺ kay Asma bint Umays (RA).", "Ang paghawak sa tawhid sa panahon ng kagipitan."),
        "dua_rahmataka_arju" to DuaText("Ang Iyong Awa ay Inaasahan Ko", "O Allah, awa mo ang aking inaasahan, kaya huwag mo akong ipaubaya sa aking sarili kahit isang kisap mata, at ayusin mo ang lahat ng aking mga gawain. Walang diyos maliban sa Iyo.", "Ang dua ng nasa kagipitan (Da'awat al-makrub).", "Tinawag ito ng Propeta ﷺ na dua ng isang nasa pagkabalisa."),
        "dua_against_enemy_ahzab" to DuaText("Laban sa Hukbo ng Kaaway", "O Allah, Tagapaghayag ng Aklat, Mabilis sa pagtutuos! Talunin ang mga confederates. O Allah, talunin mo sila at kalugin sila.", "Laban sa kaaway - ang dua ng Labanan ng mga Confederates.", "Ang ﷺ dua ng Propeta laban sa kaaway."),
        "dua_anta_adudi" to DuaText("Ikaw Ang Aking Suporta", "O Allah, Ikaw ang aking suporta at aking katulong. Sa pamamagitan mo ako ay nagpaplano, sa pamamagitan mo ako sumusulong at sa pamamagitan mo ako lalaban.", "Bago ang isang paligsahan o isang malaking hamon.", "Ang Propeta ﷺ ay nagsabi nito sa labanan."),
        "dua_ikfinihim" to DuaText("Sapat na Ako Laban sa Kanila", "O Allah, sapat na sa akin laban sa kanila kung ano ang ibig Mo.", "Laban sa kasamaan ng mga mapang-api — ang dua ng bata sa kwento ng People of the Ditch.", "Iniligtas ni Allah ang bata mula sa mga mapang-api."),
        "dua_qadarullah" to DuaText("Kapag May Mangyayari", "Ito ay kautusan ng Allah, at ginawa Niya ang Kanyang nais.", "Kapag may nangyaring hindi kanais-nais, imbes na sabihing 'if only'.", "'Kung lamang' ay nagbubukas ng pinto kay Shaytan."),
        "dua_ala_kulli_hal" to DuaText("Papuri sa Bawat Sitwasyon", "Ang lahat ng papuri ay para sa Allah sa bawat sitwasyon.", "Kapag may nangyaring hindi nagustuhan.", "Sinabi ito ng Propeta ﷺ sa pagharap sa isang bagay na hindi niya nagustuhan."),
        "dua_dogs_barking" to DuaText("Nakarinig ng mga Asong Tumahol sa Gabi", "Ako ay nagpapakupkop kay Allah mula sa Shaytan, ang isinumpa.", "Kapag naririnig ang mga aso na tumatahol o ang isang asno ay umuungol sa gabi.", "Nakikita nila ang hindi mo nakikita."),
        "dua_leaving_home_adilla" to DuaText("Kanlungan mula sa Pagkaligaw", "O Allah, ako ay nagpapakupkop sa Iyo na baka ako ay maligaw o maligaw, baka ako ay madulas o madulas, baka ako ay makagawa ng mali o mali, at baka ako ay kumilos nang may katangahan o tratuhin nang walang kabuluhan.", "Paglabas ng bahay — isinalaysay ni Umm Salamah (RA).", "Ang Propeta ﷺ ay binibigkas ito sa tuwing siya ay umalis sa kanyang bahay."),
        "dua_ascending_descending" to DuaText("Paakyat at Pababa", "Si Allah ang Pinakamadakila (kapag umaakyat). — Luwalhati sa Allah (kapag bumaba).", "Sa paglalakbay, sabihin ang 'Allahu Akbar' kapag aakyat at 'SubhanAllah' kapag pababa.", "Ang pagsasagawa ng mga Kasamahan (RA) habang naglalakbay."),
        "dua_traveller_sahar" to DuaText("Dua ng manlalakbay bago magbukang-liwayway", "Isang tagapakinig ang nakarinig (at nagpasa) ng ating papuri kay Allah at sa Kanyang mabubuting pabor sa atin. Panginoon namin, samahan mo kami at ipagkaloob Mo sa amin ang Iyong biyaya — (sinasabi ko ito) na nagpapakupkop kay Allah mula sa Apoy.", "Sa isang paglalakbay, bago madaling araw.", "Sinabi ito ng Propeta ﷺ bago madaling araw kapag naglalakbay."),
        "dua_zawwadakallah" to DuaText("Sa Manlalakbay: Magkaloob nawa si Allah ng Taqwa", "Nawa'y bigyan ka ng Allah ng taqwa para sa iyong paglalakbay, patawarin ang iyong mga kasalanan at gawing madali para sa iyo saan ka man naroroon.", "Kapag nagpaalam sa isang manlalakbay.", "Ang Propeta ﷺ ay nagbigay ng dalawang ito sa isang taong naglalakbay."),
        "dua_traveller_to_resident" to DuaText("Manlalakbay sa mga Nananatili sa Likod", "Ipinagkatiwala ko kayo kay Allah, na hindi mawawala ang mga pagtitiwala.", "Sabi ng manlalakbay nang magpaalam sa pamilya.", "Ipagkatiwala ang kaligtasan ng pamilya kay Allah."),
        "dua_entering_village" to DuaText("Pagpasok sa isang Bayan o Nayon", "O Allah, Panginoon ng pitong langit at lahat ng kanilang lilim, Panginoon ng pitong lupa at lahat ng kanilang dinadala, Panginoon ng mga diyablo at lahat ng kanilang naliligaw, Panginoon ng mga hangin at lahat ng kanilang ikinakalat! Hinihiling namin sa Iyo ang kabutihan ng bayang ito at ang kabutihan ng mga tao nito, at nagpapakupkop kami sa Iyo mula sa kasamaan nito, kasamaan ng mga tao nito at kasamaan ng kung ano ang nasa loob nito.", "Bago pumasok sa isang bayan o lungsod.", "Binibigkas ito ng Propeta ﷺ sa tuwing nais niyang pumasok sa isang bayan."),
        "dua_vehicle_stumbles" to DuaText("Kapag Natisod Ang Sasakyan", "Sa ngalan ni Allah.", "Kapag nadulas o natitisod ang bundok o sasakyan, sa halip na sabihing 'Mapahamak nawa si Shaytan'.", "Ang pagsasabi ng Bismillah ay nagpapaliit kay Shaytan na kasing laki ng langaw."),
        "dua_ajz_kasal_haram" to DuaText("Kanlungan mula sa Kahinaan at Katandaan", "O Allah, ako ay nagpapakupkop sa Iyo mula sa kawalan ng kakayahan at katamaran, mula sa kaduwagan at katandaan, mula sa mga pagsubok sa buhay at kamatayan, at mula sa parusa sa libingan.", "Isang komprehensibong pang-araw-araw na dua ng kanlungan.", "Isang dua ang Propeta ﷺ na madalas na ginawa."),
    )
}
